        with open(hw_path, "w") as file_out:
            for line in lines:
                idx = line.find('//')
                if idx == 0:
                    continue
                elif idx == -1:
                    file_out.write(line+'\n')
                else:
                    file_out.write(line[:idx]+'\n')

